"use strict";(self.webpackChunkenablemodel=self.webpackChunkenablemodel||[]).push([[2311],{1859:e=>{e.exports=JSON.parse('{"permalink":"/blog/how-enable-model-explains-disabled-entrepreneurship","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-07-17-how-enable-model-explains-disabled-entrepreneurship.md","source":"@site/blog/2025-07-17-how-enable-model-explains-disabled-entrepreneurship.md","title":"Why disabled people start more businesses, read through the ENABLE Model","description":"Working-age Americans with disabilities run their own businesses at a higher rate than their non-disabled counterparts. The U.S. Bureau of Labor Statistics has tracked the self-employment gap through the Current Population Survey Disability Supplement since the late 2000s, and the disabled self-employment share has sat above the non-disabled share in almost every year the series reports. Lisa Schur, Douglas Kruse, and Peter Blanck have published on the underlying employment and self-employment patterns from Rutgers University and Syracuse University across two decades of research.","date":"2025-07-17T00:00:00.000Z","tags":[],"readingTime":5.24,"hasTruncateMarker":true,"authors":[{"name":"Lawrence (Larry) Weru","title":"Discerner-Uniter","url":"https://lweru.com","page":{"permalink":"/blog/authors/all-larry-weru-articles"},"imageURL":"https://github.com/LDubya.png","key":"lweru"}],"frontMatter":{"slug":"how-enable-model-explains-disabled-entrepreneurship","title":"Why disabled people start more businesses, read through the ENABLE Model","authors":["lweru"]},"unlisted":false,"prevItem":{"title":"On the Self-Interest of Accessibility Manifestations","permalink":"/blog/on-the-self-interest-of-accessibility-manifestations"},"nextItem":{"title":"Introducing the ENABLE Model","permalink":"/blog/introducing-enable"}}')},8453:(e,t,s)=>{s.d(t,{R:()=>r,x:()=>o});var a=s(6540);const n={},i=a.createContext(n);function r(e){const t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),a.createElement(i.Provider,{value:t},e.children)}},9241:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>d,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>a,toc:()=>l});var a=s(1859),n=s(4848),i=s(8453);const r={slug:"how-enable-model-explains-disabled-entrepreneurship",title:"Why disabled people start more businesses, read through the ENABLE Model",authors:["lweru"]},o=void 0,d={authorsImageUrls:[void 0]},l=[{value:"Necessity, not preference",id:"necessity-not-preference",level:2},{value:"The skills the compensations cultivate",id:"the-skills-the-compensations-cultivate",level:2},{value:"Where the capital sits",id:"where-the-capital-sits",level:2},{value:"What the gap means",id:"what-the-gap-means",level:2}];function h(e){const t={a:"a",em:"em",h2:"h2",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"Working-age Americans with disabilities run their own businesses at a higher rate than their non-disabled counterparts. The U.S. Bureau of Labor Statistics has tracked the self-employment gap through the Current Population Survey Disability Supplement since the late 2000s, and the disabled self-employment share has sat above the non-disabled share in almost every year the series reports. Lisa Schur, Douglas Kruse, and Peter Blanck have published on the underlying employment and self-employment patterns from Rutgers University and Syracuse University across two decades of research."}),"\n",(0,n.jsx)(t.p,{children:"The conventional reading treats this gap as a story about grit. The ENABLE Model reads it as a story about what builders did not build."}),"\n",(0,n.jsx)(t.h2,{id:"necessity-not-preference",children:"Necessity, not preference"}),"\n",(0,n.jsxs)(t.p,{children:["When platform vendors, employers, and service providers skip ",(0,n.jsx)(t.a,{href:"/docs/builder-side",children:"builder-side interventions"}),", disabled workers absorb the shortfall through ",(0,n.jsx)(t.a,{href:"/docs/navigator-side",children:"navigator-side compensations"}),". Qualitative research on disabled entrepreneurship, including work by Sarah Parker Harris, Maija Renko, and Kate Caldwell at the University of Illinois at Chicago, has repeatedly found that disabled founders name inaccessible workplaces, hostile hiring processes, benefit-cliff penalties, and supervisors who refused reasonable accommodations as direct drivers of the decision to start a business. The workers who founded companies had already spent years ",(0,n.jsx)(t.a,{href:"/docs/navigator-side/human-help",children:"asking for help"}),", ",(0,n.jsx)(t.a,{href:"/docs/navigator-side/user-workarounds",children:"improvising workarounds"}),", ",(0,n.jsx)(t.a,{href:"/docs/navigator-side/switch-to-alternative",children:"switching to alternative tools"}),", and ",(0,n.jsx)(t.a,{href:"/docs/navigator-side/endure-inaccessibility",children:"enduring inaccessibility"})," inside wage jobs that refused to accommodate them. Starting a company moved the locus of control from a builder who would not ",(0,n.jsx)(t.a,{href:"/docs/builder-side/resource-provisioning",children:"provision resources"})," to a founder who could."]}),"\n",(0,n.jsx)(t.p,{children:"The Americans with Disabilities Act reached hiring discrimination in 1990. The Bureau of Labor Statistics reports a disability employment rate that has moved within a narrow band since the law passed, well below the non-disabled rate. Social Security Insurance asset limits, which Congress set at $2,000 for an individual and has not updated since 1989, punish disabled workers for saving. The combination pushes disabled workers toward contingent and self-employed work that sits outside the benefit cliff for most Americans but exposes them to its worst features."}),"\n",(0,n.jsx)(t.h2,{id:"the-skills-the-compensations-cultivate",children:"The skills the compensations cultivate"}),"\n",(0,n.jsxs)(t.p,{children:["Every ",(0,n.jsx)(t.a,{href:"/docs/navigator-side/user-workarounds",children:"user workaround"}),' rehearses product work. A blind software engineer who writes a custom Selenium script to click through an inaccessible vendor portal builds the same skill a founder uses to reverse-engineer a broken workflow. A wheelchair user who routes through three public-transit apps, one map overlay, and a crowd-sourced accessibility database to get to work each day practices the market research a founder does before validating a new product. Mia Mingus named "access intimacy" in 2011 to describe the attunement disabled people develop through years of negotiating accommodations. Founders of disability-focused companies report drawing on the same attunement when they interview users.']}),"\n",(0,n.jsxs)(t.p,{children:["Brenda and Moshe Weitzberg founded the nonprofit ",(0,n.jsx)(t.a,{href:"/docs/manifestations/aspiritech",children:"Aspiritech"})," in 2008 after their autistic son could not find work whose hiring process accommodated him; Aspiritech now employs more than 100 adults, over 90 percent of them on the autism spectrum, running QA and WCAG audits for paying clients. ",(0,n.jsx)(t.a,{href:"/docs/manifestations/fable",children:"Fable"})," sells disabled-user testing to Shopify, REI, John Lewis, and Typeform because those product teams had not built the panels themselves. Both organizations read the market gap directly off navigator-side experience their founders and staff had accumulated long before the product plan existed."]}),"\n",(0,n.jsx)(t.h2,{id:"where-the-capital-sits",children:"Where the capital sits"}),"\n",(0,n.jsx)(t.p,{children:'Investors treat disabled founders as outside the pattern. The Access2Funding survey, published by the UK Disability Policy Centre in 2023, reported that disabled founders were up to 400 percent less likely to secure investment than non-disabled counterparts, that 96 percent of respondents reported a lack of visibility for disability-led businesses, and that 84 percent said they lacked equal access to funding opportunities. The Kauffman Foundation, reviewing the U.S. landscape in 2015, noted that data on funding for disabled entrepreneurs was "virtually nonexistent."'}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.a,{href:"/docs/manifestations/2gether-International",children:"2Gether-International"})," launched in 2015 as the first accelerator dedicated to founders with disabilities, building the cap tables and mentorship networks that elite university accelerators had failed to extend. ",(0,n.jsx)(t.a,{href:"/docs/manifestations/enable-ventures",children:"Enable Ventures"})," launched within the Sorenson Impact Platform in June 2022 as the first impact venture fund targeting the disability wealth gap at market-rate returns. Gina Kline, Enable Ventures' founder and managing partner, ties investment tranches to measurable inclusion metrics including WCAG audits, user testing with disabled participants, and disability hiring targets. In January 2025, Enable Ventures led the Series A+ for ",(0,n.jsx)(t.a,{href:"/docs/manifestations/be-my-eyes",children:"Be My Eyes"})," and brought the National Federation of the Blind onto the cap table alongside ECMC Group, embedding a disability membership organization in the company's governance."]}),"\n",(0,n.jsx)(t.h2,{id:"what-the-gap-means",children:"What the gap means"}),"\n",(0,n.jsxs)(t.p,{children:["Over-representation in entrepreneurship is not a success story. It is a measure of what disabled workers cannot get from employers who will not accommodate them, platforms that will not build accessible tools, and benefit systems that punish savings. Marta Russell, writing in ",(0,n.jsx)(t.em,{children:"Beyond Ramps"})," (1998) and the posthumous ",(0,n.jsx)(t.em,{children:"Capitalism and Disability"})," (2019), argued that capitalism transforms impairment into disability by demanding a standardized working body and routing workers who cannot meet that standard into institutions, poverty, or entrepreneurship as a last resort. The Schur, Kruse, and Blanck data describe the last of those three routes."]}),"\n",(0,n.jsxs)(t.p,{children:["Reading the pattern through the ENABLE Model changes what counts as intervention. Employer training on disability inclusion, adjusted hiring processes, and retained accommodation staff move workers back into wage employment with stable benefits. SSI asset-limit reform, which the National Council on Disability has pressed Congress to pass since at least its 2023 progress report, restores the savings runway that non-disabled founders use before raising outside capital. Capital allocation through ",(0,n.jsx)(t.a,{href:"/docs/manifestations/2gether-International",children:"2Gether-International"}),", ",(0,n.jsx)(t.a,{href:"/docs/manifestations/enable-ventures",children:"Enable Ventures"}),", and similar funds shifts the resource-provisioning decision upstream so that disability-led companies meet the same investor gatekeeping that non-disabled founders clear on day one."]}),"\n",(0,n.jsx)(t.p,{children:"The entrepreneurship rate is evidence of what builders and policymakers shifted downstream. Every disabled founder who launched a company because the alternative was unemployment represents a pattern of upstream refusal the ENABLE Model asks readers to locate, name, and reverse."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}}}]);